import { z } from "zod";
import { CloseButton } from "./ButtonWidget.mjs";
import { jsx } from "./makeWidget.mjs";
const zConfirmProps = z.object({
    text: z.string().default("Are you sure?"),
    yes: z.string().default("OK"), // TODO -> ok, cancel
    no: z.string().default("Cancel"),
});
// TODO: yes/no -> ok/cancel and support icons etc...
export function Confirm(define) {
    return define("Confirm")
        .props(zConfirmProps)
        .children((props) => [
        jsx(CloseButton, {
            id: "confirm",
            label: props.yes,
            closeWith: true,
            hotkey: "Enter",
        }),
        jsx(CloseButton, {
            id: "cancel",
            label: props.no,
            closeWith: false,
            hotkey: "Escape",
            appearance: "button_outline",
        }),
    ])
        .render((props) => ({ text: props.text }));
}
